export { RecordButton } from "./record-button";
export { parseSerializableRecordButton } from "./schema";
export type { SerializableRecordButton } from "./schema";

"use client";

import { FC, useState, useEffect, useCallback } from "react";
import { Mic, Square, Loader2, Radio, Check as CheckIcon } from "lucide-react";
import { cn } from "@/lib/utils";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ActionButtons } from "@/components/tool-ui/shared/action-buttons";
import { useVoiceRecorderContext } from "@/contexts/voice-recorder-context";
import type { SerializableRecordButton } from "./schema";

interface RecordButtonProps extends SerializableRecordButton {
  className?: string;
  onTranscript?: (transcript: string) => void;
  onResponseAction?: (actionId: string) => void;
  isActive?: boolean; // Whether this record button is still active (last message)
}

export const RecordButton: FC<RecordButtonProps> = ({
  id,
  title,
  description,
  startLabel = "Start Recording",
  processingLabel = "Processing...",
  autoSend = true,
  promptPrefix = "Here's a transcript of the meeting, launch meeting notes workflow:\n\n",
  responseActions,
  className,
  onTranscript,
  onResponseAction,
  isActive = true,
}) => {
  const [transcript, setTranscript] = useState<string>("");
  const [recordingDuration, setRecordingDuration] = useState(0);
  const [finalDuration, setFinalDuration] = useState(0);
  const [shouldSendOnStop, setShouldSendOnStop] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [pausedDuration, setPausedDuration] = useState(0);

  // Use the shared voice recorder context
  const {
    recordingState,
    startRecording,
    stopRecording,
    sendRecording,
    hasRecording,
  } = useVoiceRecorderContext();

  // Timer for recording duration
  useEffect(() => {
    if (recordingState === "recording" && !isPaused) {
      const interval = setInterval(() => {
        setRecordingDuration((prev) => prev + 1);
      }, 1000);

      return () => clearInterval(interval);
    }
  }, [recordingState, isPaused]);

  // Handle transcription callback
  const handleTranscription = useCallback((text: string) => {
    setTranscript(text);

    if (autoSend && onTranscript) {
      // Format duration
      const mins = Math.floor(finalDuration / 60);
      const secs = finalDuration % 60;
      const durationText = mins > 0
        ? `${mins} minute${mins !== 1 ? 's' : ''} ${secs} second${secs !== 1 ? 's' : ''}`
        : `${secs} second${secs !== 1 ? 's' : ''}`;

      // Add the prefix with duration before sending
      const fullMessage = promptPrefix.replace(
        "Here's a transcript of the meeting,",
        `Here's a transcript of the meeting (duration: ${durationText}),`
      ) + text;
      onTranscript(fullMessage);
    }
  }, [autoSend, promptPrefix, onTranscript, finalDuration]);

  // Auto-send when recording stops and we have a recording
  useEffect(() => {
    const autoSendRecording = async () => {
      if (recordingState === "idle" && hasRecording && shouldSendOnStop) {
        setShouldSendOnStop(false);
        try {
          await sendRecording(handleTranscription);
        } catch (error) {
          console.error("Failed to transcribe audio:", error);
        }
      }
    };

    autoSendRecording();
  }, [recordingState, hasRecording, shouldSendOnStop, sendRecording, handleTranscription]);

  const handleClick = async () => {
    try {
      if (recordingState === "idle" && !isPaused) {
        // Start recording
        setTranscript("");
        setFinalDuration(0);
        setRecordingDuration(0);
        setPausedDuration(0);
        setIsPaused(false);
        setShouldSendOnStop(false);
        await startRecording();
      } else if (recordingState === "recording" && !isPaused) {
        // Pause recording
        setIsPaused(true);
        setPausedDuration(recordingDuration);
        stopRecording(); // Stop the media recorder but keep the state
      } else if (isPaused) {
        // Resume recording
        setIsPaused(false);
        await startRecording();
      }
    } catch (error) {
      console.error("Recording error:", error);
      alert("Failed to access microphone. Please check permissions.");
      setShouldSendOnStop(false);
      setIsPaused(false);
    }
  };

  const handleValidateAndSend = async () => {
    try {
      // Create a custom transcription handler with the current duration
      const currentDuration = pausedDuration;

      const handleTranscriptionWithDuration = (text: string) => {
        setTranscript(text);

        if (autoSend && onTranscript) {
          // Format duration
          const mins = Math.floor(currentDuration / 60);
          const secs = currentDuration % 60;
          const durationText = mins > 0
            ? `${mins} minute${mins !== 1 ? 's' : ''} ${secs} second${secs !== 1 ? 's' : ''}`
            : `${secs} second${secs !== 1 ? 's' : ''}`;

          // Add the prefix with duration before sending
          const fullMessage = promptPrefix.replace(
            "Here's a transcript of the meeting,",
            `Here's a transcript of the meeting (duration: ${durationText}),`
          ) + text;
          onTranscript(fullMessage);
        }
      };

      // Save the final duration
      setFinalDuration(currentDuration);
      setShouldSendOnStop(true);
      setIsPaused(false);

      // Trigger the send with the duration-aware handler
      if (hasRecording) {
        await sendRecording(handleTranscriptionWithDuration);
      }

      // Reset state
      setRecordingDuration(0);
      setPausedDuration(0);
    } catch (error) {
      console.error("Failed to send recording:", error);
      alert("Failed to transcribe audio. Please try again.");
    }
  };

  const formatDuration = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  };

  const getButtonIcon = () => {
    if (isPaused) {
      return <Mic className="h-8 w-8" />;
    }

    switch (recordingState) {
      case "listening":
        return <Radio className="h-8 w-8" />;
      case "recording":
        return (
          <div className="flex items-center justify-center">
            <div className="h-6 w-1.5 bg-white rounded-full mr-1" />
            <div className="h-6 w-1.5 bg-white rounded-full" />
          </div>
        );
      case "processing":
        return <Loader2 className="h-8 w-8 animate-spin" />;
      default:
        return <Mic className="h-8 w-8" />;
    }
  };

  const getButtonLabel = () => {
    if (isSessionEnded) {
      return "Session terminée";
    }

    if (isPaused) {
      return "Resume Recording";
    }

    switch (recordingState) {
      case "listening":
        return "Listening...";
      case "recording":
        return "Pause";
      case "processing":
        return processingLabel;
      default:
        return startLabel;
    }
  };

  const isListening = recordingState === "listening";
  const isRecording = recordingState === "recording" && !isPaused;
  const isProcessing = recordingState === "processing";
  const hasActiveRecording = isRecording || isPaused;
  const isSessionEnded = !isActive;

  return (
    <div
      className={cn("flex flex-col gap-3", className)}
      data-tool-ui-id={id}
      data-slot="record-button"
    >
      <Card>
        {(title || description) && (
          <CardHeader>
            {title && <CardTitle>{title}</CardTitle>}
            {description && <CardDescription>{description}</CardDescription>}
          </CardHeader>
        )}
        <CardContent className="space-y-4">
          {/* Recording Button */}
          <div className="flex flex-col items-center gap-4">
            {/* Buttons Container */}
            <div className="flex items-center gap-6">
              {/* Big Round Record Button */}
              <div className="relative">
              <button
                onClick={handleClick}
                disabled={isProcessing || isSessionEnded}
                className={cn(
                  "relative h-32 w-32 rounded-full transition-all duration-300 shadow-lg",
                  "flex items-center justify-center",
                  "focus:outline-none focus:ring-4 focus:ring-offset-2",
                  "disabled:opacity-50 disabled:cursor-not-allowed",
                  isSessionEnded && "bg-gray-500 cursor-not-allowed",
                  !isSessionEnded && isRecording && "bg-red-500 hover:bg-red-600 animate-pulse shadow-red-500/50 focus:ring-red-300",
                  !isSessionEnded && isPaused && "bg-orange-500 hover:bg-orange-600 shadow-orange-500/50 focus:ring-orange-300",
                  !isSessionEnded && isListening && "bg-blue-500 hover:bg-blue-600 shadow-blue-500/50 focus:ring-blue-300",
                  !isSessionEnded && !isRecording && !isListening && !isProcessing && !isPaused && "bg-gradient-to-br from-red-500 to-red-600 hover:from-red-600 hover:to-red-700 shadow-red-500/30 focus:ring-red-300",
                  !isSessionEnded && isProcessing && "bg-gray-400"
                )}
              >
                {/* Inner circle for depth effect */}
                <div className={cn(
                  "absolute inset-4 rounded-full transition-all duration-300",
                  isSessionEnded && "bg-gray-600",
                  !isSessionEnded && isRecording && "bg-red-600 animate-pulse",
                  !isSessionEnded && isPaused && "bg-orange-600",
                  !isSessionEnded && isListening && "bg-blue-600",
                  !isSessionEnded && !isRecording && !isListening && !isProcessing && !isPaused && "bg-red-600/80",
                  !isSessionEnded && isProcessing && "bg-gray-500"
                )} />

                {/* Icon */}
                <div className="relative z-10 text-white">
                  {isSessionEnded ? (
                    <Square className="h-8 w-8 fill-white" />
                  ) : (
                    getButtonIcon()
                  )}
                </div>
              </button>

              {/* Outer glow ring when recording */}
              {isRecording && (
                <div className="absolute inset-0 -z-10 rounded-full bg-red-500/30 blur-xl animate-pulse" />
              )}

              {/* Outer glow ring when listening */}
              {isListening && (
                <div className="absolute inset-0 -z-10 rounded-full bg-blue-500/30 blur-xl animate-pulse" />
              )}

              {/* Outer glow ring when paused */}
              {isPaused && (
                <div className="absolute inset-0 -z-10 rounded-full bg-orange-500/30 blur-xl" />
              )}
              </div>

              {/* Send to LLM Round Button - Hidden when session ended */}
              {!isSessionEnded && (
                <div className="relative">
                  <button
                    onClick={handleValidateAndSend}
                    disabled={isProcessing || !isPaused}
                    className={cn(
                      "relative h-32 w-32 rounded-full transition-all duration-300 shadow-lg",
                      "flex items-center justify-center",
                      "focus:outline-none focus:ring-4 focus:ring-offset-2",
                      "disabled:opacity-30 disabled:cursor-not-allowed",
                      isPaused && "bg-green-600 hover:bg-green-700 shadow-green-600/50 focus:ring-green-300",
                      !isPaused && "bg-green-600/50"
                    )}
                  >
                    {/* Inner circle for depth effect */}
                    <div className={cn(
                      "absolute inset-4 rounded-full transition-all duration-300",
                      isPaused && "bg-green-700",
                      !isPaused && "bg-green-700/50"
                    )} />

                    {/* Icon */}
                    <div className="relative z-10 text-white">
                      <CheckIcon className="h-8 w-8" />
                    </div>
                  </button>

                  {/* Outer glow ring when enabled */}
                  {isPaused && (
                    <div className="absolute inset-0 -z-10 rounded-full bg-green-500/30 blur-xl" />
                  )}
                </div>
              )}
            </div>

            {/* Button Labels */}
            <div className="flex gap-6 items-center justify-center">
              <p className={cn(
                "text-sm font-medium transition-colors w-32 text-center",
                isSessionEnded && "text-gray-500",
                !isSessionEnded && isRecording && "text-red-500",
                !isSessionEnded && isPaused && "text-orange-500",
                !isSessionEnded && isListening && "text-blue-500",
                !isSessionEnded && isProcessing && "text-gray-500"
              )}>
                {getButtonLabel()}
              </p>

              {!isSessionEnded && (
                <p className={cn(
                  "text-sm font-medium transition-colors w-32 text-center",
                  isPaused && "text-green-600",
                  !isPaused && "text-gray-400"
                )}>
                  Send to LLM
                </p>
              )}
            </div>

            {/* Recording Duration */}
            {(isRecording || isPaused) && !isSessionEnded && (
              <div className="flex items-center gap-2 text-sm text-muted-foreground animate-in fade-in slide-in-from-top-2 duration-200">
                <div className="flex items-center gap-1.5">
                  <div className={cn(
                    "size-2 rounded-full",
                    isRecording && "bg-red-500 animate-pulse",
                    isPaused && "bg-orange-500"
                  )} />
                  <span className="font-mono text-xs">
                    {formatDuration(isPaused ? pausedDuration : recordingDuration)}
                  </span>
                </div>
              </div>
            )}

            {/* Listening Indicator */}
            {isListening && !isRecording && !isSessionEnded && (
              <div className="flex items-center gap-2 text-sm text-blue-500 animate-in fade-in slide-in-from-top-2 duration-200">
                <div className="flex items-center gap-1.5">
                  <div className="size-2 rounded-full bg-blue-500 animate-pulse" />
                  <span className="text-xs font-medium">Listening...</span>
                </div>
              </div>
            )}

            {/* Transcript Display */}
            {transcript && !isSessionEnded && (
              <div className="w-full p-4 bg-muted rounded-lg animate-in fade-in slide-in-from-bottom-2 duration-300">
                <p className="text-sm font-medium mb-2">Transcript:</p>
                <p className="text-sm text-muted-foreground whitespace-pre-wrap">
                  {transcript}
                </p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Response Actions */}
      {responseActions && responseActions.length > 0 && (
        <ActionButtons
          actions={responseActions}
          onAction={onResponseAction}
        />
      )}
    </div>
  );
};

import type { Action } from "../shared/schema";

export interface SerializableRecordButton {
  id: string;
  title?: string;
  description?: string;
  startLabel?: string;        // Label for start recording button (default: "Start Recording")
  stopLabel?: string;         // Label for stop recording button (default: "Stop Recording")
  processingLabel?: string;   // Label while processing (default: "Processing...")
  autoSend?: boolean;         // Auto-send transcript (default: true)
  promptPrefix?: string;      // Prefix to add before transcript (default: "Here's a transcript of the meeting, launch meeting notes workflow:\n\n")
  variant?: "default" | "destructive" | "outline" | "secondary" | "ghost";
  size?: "default" | "sm" | "lg" | "icon";
  showWaveform?: boolean;     // Show audio waveform while recording (default: true)
  responseActions?: Action[]; // Additional actions after recording
}

export function parseSerializableRecordButton(data: any): SerializableRecordButton {
  return {
    id: data.id || crypto.randomUUID(),
    title: data.title,
    description: data.description,
    startLabel: data.startLabel || "Start Recording",
    stopLabel: data.stopLabel || "Stop Recording",
    processingLabel: data.processingLabel || "Processing...",
    autoSend: data.autoSend !== undefined ? data.autoSend : true,
    promptPrefix: data.promptPrefix || "Here's a transcript of the meeting, launch meeting notes workflow:\n\n",
    variant: data.variant || "default",
    size: data.size || "default",
    showWaveform: data.showWaveform !== undefined ? data.showWaveform : true,
    responseActions: data.responseActions,
  };
}

"use client";

import { FC } from "react";
import { Button } from "@/components/ui/button";
import type { Action } from "./schema";

interface ActionButtonsProps {
  actions?: Action[];
  onAction?: (actionId: string) => void;
  className?: string;
}

export const ActionButtons: FC<ActionButtonsProps> = ({
  actions,
  onAction,
  className,
}) => {
  if (!actions || actions.length === 0) return null;

  return (
    <div className={`flex flex-wrap gap-2 ${className || ""}`}>
      {actions.map((action) => (
        <Button
          key={action.id}
          variant={action.variant || "outline"}
          size="sm"
          disabled={action.disabled}
          onClick={() => onAction?.(action.id)}
          className="text-xs"
        >
          {action.label}
        </Button>
      ))}
    </div>
  );
};

/**
 * Shared types for social post components
 */

export interface Action {
  id: string;
  label: string;
  prompt?: string; // The message to send when clicked
  variant?: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link";
  disabled?: boolean;
}

export interface BaseAuthor {
  name: string;
  avatarUrl: string;
}

export interface MediaItem {
  type: "image" | "video";
  url: string;
  alt?: string;
  aspectRatio?: number;
}

export interface LinkPreview {
  url: string;
  title?: string;
  description?: string;
  imageUrl?: string;
  domain?: string;
}

export interface BaseStats {
  likes?: number;
  shares?: number;
  comments?: number;
}

"use client";

import { createContext, useContext, type ReactNode, type RefObject } from "react";
import { useVoiceRecorder, type RecordingState } from "@/hooks/use-voice-recorder";
import { useChatKit } from "@/lib/chat-kit";

interface VoiceRecorderContextType {
  recordingState: RecordingState;
  startRecording: () => Promise<void>;
  stopRecording: () => void;
  sendRecording: (onTranscription: (text: string) => void) => Promise<void>;
  cancelRecording: () => void;
  startListeningMode: () => Promise<void>;
  stopListeningMode: () => void;
  pauseListening: () => void;
  resumeListening: () => void;
  hasRecording: boolean;
  audioContextRef: RefObject<AudioContext | null>;
  analyserRef: RefObject<AnalyserNode | null>;
}

const VoiceRecorderContext = createContext<VoiceRecorderContextType | null>(null);

export function VoiceRecorderProvider({
  children,
  onVoiceDetected,
}: {
  children: ReactNode;
  onVoiceDetected?: () => void;
}) {
  const { transcribe } = useChatKit();
  const recorder = useVoiceRecorder(onVoiceDetected, transcribe);

  return (
    <VoiceRecorderContext.Provider value={recorder}>
      {children}
    </VoiceRecorderContext.Provider>
  );
}

export function useVoiceRecorderContext() {
  const context = useContext(VoiceRecorderContext);
  if (!context) {
    throw new Error("useVoiceRecorderContext must be used within VoiceRecorderProvider");
  }
  return context;
}

import { useState, useRef, useCallback, useEffect } from "react";

export type RecordingState = "idle" | "listening" | "recording" | "processing";

export type Transcribe = (audio: File) => Promise<string>;

export function useVoiceRecorder(onVoiceDetected?: () => void, transcribe?: Transcribe) {
  const transcribeRef = useRef(transcribe);
  transcribeRef.current = transcribe;
  const [recordingState, setRecordingState] = useState<RecordingState>("idle");
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  // VAD (Voice Activity Detection) refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const silenceTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const vadIntervalRef = useRef<NodeJS.Timeout | null>(null);
  const isRecordingFromVADRef = useRef(false);
  const isListeningActiveRef = useRef(false);
  const silenceScheduledRef = useRef(false);
  const isListeningPausedRef = useRef(false);

  const startRecording = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      // Try formats most speech-to-text services accept, in order
      let mimeType = "audio/mp4";
      let fileExtension = "m4a";

      if (MediaRecorder.isTypeSupported("audio/mp4")) {
        mimeType = "audio/mp4";
        fileExtension = "m4a";
      } else if (MediaRecorder.isTypeSupported("audio/webm;codecs=opus")) {
        // Try webm with opus codec as fallback
        mimeType = "audio/webm;codecs=opus";
        fileExtension = "webm";
      } else if (MediaRecorder.isTypeSupported("audio/webm")) {
        mimeType = "audio/webm";
        fileExtension = "webm";
      } else {
        // Last resort - let browser decide
        mimeType = "";
        fileExtension = "webm";
      }

      const mediaRecorder = new MediaRecorder(stream, mimeType ? { mimeType } : undefined);

      chunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          chunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = () => {
        const actualMimeType = mimeType || mediaRecorder.mimeType;
        const blob = new Blob(chunksRef.current, { type: actualMimeType });
        setAudioBlob(blob);

        // Store the file extension for later use
        (blob as any).__fileExtension = fileExtension;

        // Stop all tracks to release the microphone
        stream.getTracks().forEach((track) => track.stop());
      };

      mediaRecorder.start();
      mediaRecorderRef.current = mediaRecorder;
      setRecordingState("recording");
    } catch (error) {
      throw error;
    }
  }, []);

  const stopRecording = useCallback(() => {
    if (mediaRecorderRef.current && recordingState === "recording") {
      mediaRecorderRef.current.stop();
      setRecordingState("idle");
    }
  }, [recordingState]);

  const sendRecording = useCallback(
    async (onTranscription: (text: string) => void) => {
      if (!audioBlob) {
        return;
      }

      setRecordingState("processing");

      try {
        if (!transcribeRef.current) {
          throw new Error("No transcribe adapter configured");
        }

        const extension = (audioBlob as any).__fileExtension || "m4a";
        const file = new File([audioBlob], `recording.${extension}`, {
          type: audioBlob.type,
        });

        const text = await transcribeRef.current(file);

        if (text) {
          onTranscription(text);
        }

        setAudioBlob(null);

        // Return to listening mode if still active, otherwise go to idle
        if (isListeningActiveRef.current) {
          setRecordingState("listening");
        } else {
          setRecordingState("idle");
        }
      } catch (error) {
        // Return to listening mode if still active, otherwise go to idle
        if (isListeningActiveRef.current) {
          setRecordingState("listening");
        } else {
          setRecordingState("idle");
        }
        throw error;
      }
    },
    [audioBlob]
  );

  const cancelRecording = useCallback(() => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
    }
    setAudioBlob(null);
    setRecordingState("idle");
  }, []);

  // VAD: Detect audio level
  const getAudioLevel = useCallback(() => {
    if (!analyserRef.current) return 0;

    const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
    analyserRef.current.getByteFrequencyData(dataArray);

    // Calculate average volume
    const average = dataArray.reduce((acc, val) => acc + val, 0) / dataArray.length;
    return average;
  }, []);

  // Helper: Start recording with existing stream
  const startRecordingWithStream = useCallback(async (stream: MediaStream) => {
    try {
      // Try different formats most speech-to-text services accept, in order
      let mimeType = "audio/mp4";
      let fileExtension = "m4a";

      if (MediaRecorder.isTypeSupported("audio/mp4")) {
        mimeType = "audio/mp4";
        fileExtension = "m4a";
      } else if (MediaRecorder.isTypeSupported("audio/webm;codecs=opus")) {
        mimeType = "audio/webm;codecs=opus";
        fileExtension = "webm";
      } else if (MediaRecorder.isTypeSupported("audio/webm")) {
        mimeType = "audio/webm";
        fileExtension = "webm";
      } else {
        mimeType = "";
        fileExtension = "webm";
      }

      const mediaRecorder = new MediaRecorder(stream, mimeType ? { mimeType } : undefined);

      chunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          chunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = () => {
        const actualMimeType = mimeType || mediaRecorder.mimeType;
        const blob = new Blob(chunksRef.current, { type: actualMimeType });
        setAudioBlob(blob);

        // Store the file extension for later use
        (blob as any).__fileExtension = fileExtension;

        // If still in listening mode, return to listening state
        // Don't stop the stream - we're in listening mode
        if (isListeningActiveRef.current) {
          setRecordingState("listening");
        } else {
          // Not in listening mode anymore, go to idle
          setRecordingState("idle");
        }
      };

      mediaRecorder.start();
      mediaRecorderRef.current = mediaRecorder;
      setRecordingState("recording");
    } catch (error) {
      throw error;
    }
  }, []);

  // VAD: Start auto-recording when voice is detected
  const startListeningMode = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
        },
      });
      streamRef.current = stream;

      // Set up audio context for VAD
      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const analyser = audioContext.createAnalyser();
      const source = audioContext.createMediaStreamSource(stream);

      analyser.fftSize = 2048;
      analyser.smoothingTimeConstant = 0.8;
      source.connect(analyser);

      audioContextRef.current = audioContext;
      analyserRef.current = analyser;
      isListeningActiveRef.current = true;

      setRecordingState("listening");

      // Voice threshold (adjust based on testing)
      const VOICE_THRESHOLD = 30; // Lower = more sensitive
      const SILENCE_DURATION = 2000; // ms of silence before stopping

      // Start VAD monitoring
      vadIntervalRef.current = setInterval(() => {
        if (!isListeningActiveRef.current) {
          return;
        }

        // Skip VAD check if paused
        if (isListeningPausedRef.current) {
          return;
        }

        const audioLevel = getAudioLevel();

        // Voice detected - start recording if not already recording
        if (audioLevel > VOICE_THRESHOLD && isListeningActiveRef.current && !isRecordingFromVADRef.current) {
          // Notify that voice was detected (for stopping audio playback)
          if (onVoiceDetected) {
            onVoiceDetected();
          }

          isRecordingFromVADRef.current = true;
          silenceScheduledRef.current = false; // Reset silence flag when starting new recording

          // Clear any existing silence timeout
          if (silenceTimeoutRef.current) {
            clearTimeout(silenceTimeoutRef.current);
            silenceTimeoutRef.current = null;
          }

          // Start recording with existing stream
          startRecordingWithStream(stream);
        }

        // Voice continues - cancel silence timeout
        if (audioLevel > VOICE_THRESHOLD && isRecordingFromVADRef.current) {
          // Voice is still active, cancel any scheduled silence timeout
          if (silenceScheduledRef.current) {
            clearTimeout(silenceTimeoutRef.current!);
            silenceTimeoutRef.current = null;
            silenceScheduledRef.current = false;
          }
        }

        // Silence detected - schedule stop ONCE if currently recording
        if (audioLevel <= VOICE_THRESHOLD && isRecordingFromVADRef.current && !silenceScheduledRef.current) {
          silenceScheduledRef.current = true; // Mark that we've scheduled the timeout

          // Schedule stop after silence duration
          silenceTimeoutRef.current = setTimeout(() => {
            if (mediaRecorderRef.current && isRecordingFromVADRef.current) {
              mediaRecorderRef.current.stop();
              isRecordingFromVADRef.current = false;
              silenceScheduledRef.current = false; // Reset for next recording
            }
          }, SILENCE_DURATION);
        }
      }, 100); // Check every 100ms
    } catch (error) {
      isListeningActiveRef.current = false;
      throw error;
    }
  }, [getAudioLevel, stopRecording, startRecordingWithStream]);

  // Stop listening mode
  const stopListeningMode = useCallback(() => {
    // Mark listening as inactive
    isListeningActiveRef.current = false;
    silenceScheduledRef.current = false; // Reset silence flag

    // Clear VAD interval
    if (vadIntervalRef.current) {
      clearInterval(vadIntervalRef.current);
      vadIntervalRef.current = null;
    }

    // Clear silence timeout
    if (silenceTimeoutRef.current) {
      clearTimeout(silenceTimeoutRef.current);
      silenceTimeoutRef.current = null;
    }

    // Stop recording if active
    if (mediaRecorderRef.current && isRecordingFromVADRef.current) {
      mediaRecorderRef.current.stop();
      isRecordingFromVADRef.current = false;
    }

    // Close audio context
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }

    // Stop all tracks
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }

    analyserRef.current = null;
    setRecordingState("idle");
  }, []);

  // Pause listening (keeps stream active but stops VAD monitoring)
  const pauseListening = useCallback(() => {
    if (isListeningActiveRef.current && !isListeningPausedRef.current) {
      isListeningPausedRef.current = true;
    }
  }, []);

  // Resume listening (resumes VAD monitoring)
  const resumeListening = useCallback(() => {
    if (isListeningActiveRef.current && isListeningPausedRef.current) {
      isListeningPausedRef.current = false;
    }
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      stopListeningMode();
    };
  }, [stopListeningMode]);

  return {
    recordingState,
    startRecording,
    stopRecording,
    sendRecording,
    cancelRecording,
    startListeningMode,
    stopListeningMode,
    pauseListening,
    resumeListening,
    hasRecording: audioBlob !== null,
    audioContextRef,
    analyserRef,
  };
}

"use client";

import { createContext, useContext, type ReactNode } from "react";

/**
 * Everything the kit needs from your backend, as plain async functions.
 * Leave one out and the matching piece of UI hides itself.
 */
export interface ChatKitAdapters {
  /** Speech to text. Enables the mic button and hands-free mode. */
  transcribe?: (audio: File) => Promise<string>;
  /** Text to speech. Enables the "play" action and spoken replies in hands-free mode. */
  synthesize?: (text: string) => Promise<Blob>;
  /** Follow-up prompts for an assistant message. A `suggestions` data part works too. */
  getSuggestions?: (messageId: string) => Promise<string[]>;
}

export interface Starter {
  title: string;
  label: string;
  prompt: string;
}

export interface ChatKitConfig extends ChatKitAdapters {
  welcome?: { title: string; subtitle?: string };
  starters?: Starter[];
  placeholder?: string;
}

const defaults: ChatKitConfig = {
  welcome: { title: "Hello.", subtitle: "How can I help today?" },
  starters: [],
  placeholder: "Send a message...",
};

const ChatKitContext = createContext<ChatKitConfig>(defaults);

export function ChatKitProvider({
  children,
  ...config
}: ChatKitConfig & { children: ReactNode }) {
  return (
    <ChatKitContext.Provider value={{ ...defaults, ...config }}>
      {children}
    </ChatKitContext.Provider>
  );
}

export function useChatKit() {
  return useContext(ChatKitContext);
}
